question.answer:
from types import TracebackType

LOG: list[str] = []


# Supplied. Do not change this class.
class Valve:
    """A valve that must be shut again however the block ends."""

    def __init__(self, name: str) -> None:
        self.name = name

    def flow(self, litres: int) -> int:
        LOG.append(f"flow {self.name} {litres}")
        return litres

    def __enter__(self) -> "Valve":
        LOG.append(f"open {self.name}")
        return self

    def __exit__(self, exc_type: type[BaseException] | None,
                 exc_value: BaseException | None,
                 traceback: TracebackType | None) -> None:
        LOG.append(f"shut {self.name}")


def pour(name: str, litres: int) -> int:
    with Valve(name) as valve:
        return valve.flow(litres)


def pour_many(names: list[str], litres: int) -> int:
    total = 0
    for name in names:
        with Valve(name) as valve:
            total += valve.flow(litres)
    return total


def pour_and_fail(name: str) -> str:
    try:
        with Valve(name) as valve:
            valve.flow(1)
            raise ValueError("line burst")
    except ValueError as problem:
        return f"caught {problem}"

from types import TracebackType

LOG: list[str] = []


# Supplied. Do not change this exception.
class SensorError(Exception):
    """Raised when a reading cannot be trusted."""


class Session:
    def __init__(self, name: str) -> None:
        self.name = name
        self.readings: list[int] = []

    def __enter__(self) -> list[int]:
        LOG.append(f"start {self.name}")
        return self.readings

    def __exit__(self, exc_type: type[BaseException] | None,
                 exc_value: BaseException | None,
                 traceback: TracebackType | None) -> None:
        outcome = "clean" if exc_type is None else exc_type.__name__
        LOG.append(f"end {self.name} {outcome}")


class Muffler:
    def __init__(self, name: str) -> None:
        self.name = name
        self.swallowed: str | None = None

    def __enter__(self) -> "Muffler":
        LOG.append(f"start {self.name}")
        return self

    def __exit__(self, exc_type: type[BaseException] | None,
                 exc_value: BaseException | None,
                 traceback: TracebackType | None) -> bool:
        self.swallowed = None if exc_value is None else str(exc_value)
        LOG.append(f"end {self.name}")
        # Returning True throws the failure away. This class is the counter-example.
        return True


def take(name: str, values: list[int]) -> list[int]:
    with Session(name) as readings:
        for value in values:
            if value < 0:
                raise SensorError(f"{value} is below zero")
            readings.append(value)
    return readings

