import functools
from collections.abc import Callable, Iterable, Iterator
from contextlib import contextmanager, ExitStack
from types import TracebackType
from typing import Any

JOURNAL: list[str] = []
ATTEMPTS: list[str] = []
PENDING_FAILURES = 2


# Supplied. Do not change this exception.
class ValveError(Exception):
    pass


# Supplied from the decorators topic. Do not change it.
def retry(times: int) -> Callable[[Callable[..., Any]], Callable[..., Any]]:
    def decorate(func: Callable[..., Any]) -> Callable[..., Any]:
        @functools.wraps(func)
        def wrapper(*args: Any, **kwargs: Any) -> Any:
            last = None
            for _ in range(times):
                try:
                    return func(*args, **kwargs)
                except ValveError as exc:
                    last = exc
            raise last
        return wrapper
    return decorate


# Supplied. Do not change it.
@retry(3)
def open_valve(name: str) -> str:
    """Open the named valve. It sticks for a while first."""
    global PENDING_FAILURES
    ATTEMPTS.append(name)
    if PENDING_FAILURES > 0:
        PENDING_FAILURES -= 1
        raise ValveError(f"{name} stuck")
    return f"{name} open"


class Transaction:
    def __init__(self, name: str) -> None:
        self.name = name
        self.last_exception: str | None = None

    def __enter__(self) -> "Transaction":
        JOURNAL.append(f"BEGIN {self.name}")
        return self

    def __exit__(self, exc_type: type[BaseException] | None,
                 exc_value: BaseException | None,
                 traceback: TracebackType | None) -> bool:
        self.last_exception = None if exc_type is None else exc_type.__name__
        JOURNAL.append(f"{'COMMIT' if exc_type is None else 'ROLLBACK'} {self.name}")
        # Returning True here would swallow the failure and report a clean run.
        return False


@contextmanager
def transaction(name: str) -> Iterator[str]:
    JOURNAL.append(f"BEGIN {name}")
    done = False
    try:
        yield name
        done = True
    finally:
        JOURNAL.append(f"{'COMMIT' if done else 'ROLLBACK'} {name}")


# A retry cannot be a context manager. __exit__ is handed the exception only after
# the block has already finished running, and it has no way to run those statements
# a second time. A decorator can, because it holds the callable itself.


def open_many(names: Iterable[str]) -> int:
    with ExitStack() as stack:
        for name in names:
            stack.enter_context(Transaction(name))
        return len(names)
